{
     "title": "CSCI-452: Systems Programming - Hardware Interface Foundations",
     "learningObjectives": [
       "Define the operational boundaries between user mode and privileged kernel mode in a multiprogramming environment.",
       "Explain how system calls and traps transfer control from user code to kernel services while preserving processor state.",
       "Apply hardware interface design principles by mapping virtual addresses to physical memory using page tables and managing concurrent access with locks"
     ],
     "beats": [
       {
         "title": "1. Multiprogramming Environment Overview",
         "claim": "A multiprogramming environment allows multiple processes to execute concurrently by sharing system resources while maintaining isolation.",
         "example": "A server running multiple web requests simultaneously uses separate address spaces for each process to prevent memory corruption.",
         "visualDirection": "Display a diagram showing three isolated process bubbles sharing a central CPU and memory bus, with arrows indicating context switches.",
         "sourceIds": ["rit-csci-452"]
       },
       {
         "title": "2. Process Definition and State",
         "claim": "A process combines an address space with execution state and operating-system resources to function as an independent unit of scheduling.",
         "example": "Each running application maintains its own stack, heap, and open file descriptors, preventing data leakage between applications.",
         "visualDirection": "Show a split-screen comparison of a process structure containing an address space block, execution state register, and resource list.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "3. User Mode vs. Privileged Kernel Mode",
         "claim": "The operating system enforces a strict boundary between user mode and privileged kernel code to protect system integrity.",
         "example": "A user program cannot directly modify the page table or interrupt controller registers without triggering a protection fault.",
         "visualDirection": "Illustrate a two-tiered architecture diagram with a 'User Mode' zone and a 'Kernel Mode' zone separated by a security boundary line.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "4. System Call Mechanism",
         "claim": "A system call transfers control from user code to a privileged kernel service to perform privileged operations safely.",
         "example": "Calling read() from a user program triggers a trap that switches execution to the kernel's file system driver.",
         "visualDirection": "Draw a flowchart showing user code invoking a system call, transitioning to kernel code, and returning control with results.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "5. Trap Handling and Processor State",
         "claim": "A trap records processor state so the kernel can handle a system call, exception, or interrupt without losing execution context.",
         "example": "When an interrupt occurs, the CPU automatically saves the instruction pointer, registers, and flags to a stack frame for later restoration.",
         "visualDirection": "Display a stack diagram showing saved registers and the instruction pointer pushed onto the kernel stack during a trap.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "6. Virtual to Physical Memory Mapping",
         "claim": "Page tables map virtual addresses to physical memory with permission bits to enable safe memory management.",
         "example": "A virtual address is decomposed into a page number and offset, then translated by the MMU using the page table to locate the actual physical frame.",
         "visualDirection": "Show a two-column table mapping virtual page numbers to physical page numbers, with checkmarks indicating read/write/execute permissions.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "7. RISC-V ISA and Memory Operations",
         "claim": "The RISC-V ISA defines programmer-visible instructions, registers, memory operations, control transfer, exceptions, and ordering behavior.",
         "example": "Load instructions transfer data from memory into registers, while store instructions transfer register data to memory according to defined rules.",
         "visualDirection": "Present a side-by-side comparison of a load instruction and a store instruction with register and memory operand labels.",
         "sourceIds": ["riscv-unprivileged"]
       },
       {
         "title": "8. Memory Ordering and Dependencies",
         "claim": "Memory-ordering rules constrain how memory operations may be observed, preserving data dependencies and architectural state.",
         "example": "A compiler or CPU may reorder independent memory accesses for performance, but must maintain the relative order of dependent operations.",
         "visualDirection": "Show a sequence of memory operations with arrows indicating dependency chains and ordering constraints between them.",
         "sourceIds": ["riscv-unprivileged"]
       },
       {
         "title": "9. Locks and Concurrency Invariants",
         "claim": "Locks protect invariants when concurrent execution can access shared state, preventing race conditions in kernel services.",
         "example": "A mutex lock ensures that only one process can modify the process control block at a time during context switching.",
         "visualDirection": "Illustrate a lock acquisition and release cycle with two concurrent threads waiting for and releasing a shared resource.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "10. Practical Analysis Checklist",
         "claim": "Systems programming requires verifying that hardware interfaces correctly handle interrupts, manage memory mappings, and enforce isolation in a multiprogramming environment.",
         "example": "A driver must validate interrupt flags, update page table entries, and acquire locks before modifying shared device registers.",
         "visualDirection": "List a checklist with checkboxes for: interrupt handling, page table validation, lock acquisition, and isolation verification.",
         "sourceIds": ["rit-csci-452", "mit-xv6-book"]
       }
     ]
   }
